package net.officefloor.hq.app.person;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.alias.Alias;
import net.officefloor.hq.app.alias.AliasRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val Sheet sheet, @Val List<Person> people, AliasRepository aliases, NameTree tree,
            PersonRepository repository, ObjectResponse<List<PersonResponse>> response) {
        Set<String> taken = tree.taken(sheet.id());
        Map<Long, List<String>> byPerson = new HashMap<>();
        if (!taken.isEmpty()) {
            for (Alias a : aliases.findAll(sheet.id())) {
                byPerson.computeIfAbsent(a.personId(), (k) -> new java.util.ArrayList<>()).add(a.alias());
            }
        }
        Map<Long, String> origins = repository.origins(sheet.id());
        Map<Long, String> tags = repository.tagsAll(sheet.id());
        response.send(people.stream().map((p) -> PersonResponse.from(p,
                NameTree.clashing(taken, p.name(), byPerson.getOrDefault(p.id(), List.of())), origins.get(p.id()),
                tags.get(p.id())))
                .toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person, tree.clashing(person, people.aliases(person.sheetId(), person.id())),
                people.origin(person.sheetId(), person.id()), people.tags(person.sheetId(), person.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as the store holds them now. */
public class RespondWithMerge {
    public void respond(@Val Merge merge, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        Person into = people.find(merge.into().sheetId(), merge.into().id());
        response.send(PersonResponse.from(into, tree.clashing(into, people.aliases(into.sheetId(), into.id())),
                people.origin(into.sheetId(), into.id()), people.tags(into.sheetId(), into.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person as they arrived on the other sheet. */
public class RespondWithTransfer {
    public void respond(@Val Transferred transferred, PersonRepository people, NameTree tree,
            ObjectResponse<PersonResponse> response) {
        Person person = transferred.person();
        response.send(PersonResponse.from(person, tree.clashing(person, people.aliases(person.sheetId(), person.id())),
                people.origin(person.sheetId(), person.id()), people.tags(person.sheetId(), person.id())));
    }
}
